109	    /** Move the claim to {@code next}; refused when the user's role may not open, settle or void it (see
110	     * {@link SettingsService#allowed}), and when its current status does not allow it (a PENDING
111	     * claim can only be voided here: it is approved or rejected instead). Settling it fixes what is due
112	     * on it then (the figure it is bound to, when a statement bound it, otherwise its person's rate then)
113	     * together with its late charge then (none on a correction); the user who opened it cannot settle it,
114	     * and a clerk's settle of it when that due is above the sheet's clerk limit (a due that is n/a is
115	     * within any limit) leaves it PENDING instead, fixing nothing, until a steward approves or rejects
116	     * it. A claim deferred on the sheet's today cannot be settled, nor one without proofs whose due is
117	     * above the proof threshold in force on its date (refused before the clerk limit is considered). A voided claim keeps its number, if it had one. */
118	    @Transactional
119	    public Claim changeStatus(String sheetId, String user, long claimId, ClaimStatus next) {
120	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
121	        Action action = switch (next) {
122	            case OPEN -> Action.OPEN;
123	            case SETTLED -> Action.SETTLE;
124	            case VOID -> Action.VOID;
125	            default -> null;
126	        };
127	        if (action != null && !settings.allowed(sheetId, user, action)) throw new ClaimNotStewardException();
128	        refuseClosed(sheetId, claim.getDate());
129	        if (!claim.getStatus().canBecome(next) || (claim.getStatus() == ClaimStatus.PENDING && next != ClaimStatus.VOID)) {
130	            throw new ClaimStatusChangeException();
131	        }
132	        if (next == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) throw new ClaimStatusChangeException();
133	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) throw new ClaimSelfSettleException();
134	        RollupService.Snapshot before = rollup.snapshot(sheetId);
135	        String number = claim.getNumber();
136	        if (next == ClaimStatus.OPEN) {
137	            number = nextNumber(sheetId, claim.getDate());
138	            claim.setOpenedBy(user);
139	        }
140	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
141	                .orElseThrow(PersonNotFoundException::new);
142	        if (next == ClaimStatus.SETTLED) {
143	            BigDecimal figure = claim.isStated() ? claim.getStatedDue() : rollup.dueOf(claim, person);
144	            BigDecimal due = figure == null ? null : figure.add(rollup.lateChargeOf(claim, figure));
145	            refuseUnproved(claim, due);
146	            if (overLimit(sheetId, user, due)) next = ClaimStatus.PENDING;
147	            else claim.setSettledDue(due);
148	        }
149	        claim.setStatus(next);
150	        claim.setNumber(number);
151	        claims.flush();
152	        log(user, person, claim);
153	        String event = switch (next) {
154	            case OPEN -> "CLAIM_OPENED";
155	            case PENDING -> "CLAIM_PENDING";
156	            case SETTLED -> "CLAIM_SETTLED";
157	            case VOID -> "CLAIM_VOIDED";
158	            case DRAFT -> throw new IllegalStateException();
159	        };
160	        if (next == ClaimStatus.SETTLED) {
161	            record(event, user, person, claim, number, "due=" + dueText(claim.getSettledDue()));
162	        } else {
163	            record(event, user, person, claim, number);
164	        }
165	        rollup.recordSince(sheetId, user, before);
166	        return claim;
