        audit.change("PATRON_ADDED", sheetId, user, "name=" + person.getName(), "patron=" + patron.getName());
        return added;
    }

    /** Refuses a name another person on the sheet (other than {@code self}) already has. */
    private void requireFree(String sheetId, String name, Long self) {
        people.findBySheetIdAndNameKey(sheetId, Person.keyOf(name))
                .filter(other -> !other.getId().equals(self))
                .ifPresent(other -> {
                    throw new PersonNameTakenException();
                });
    }
}
-- The holds a person has been put on, each from a date and, optionally, to one (both included): an
-- OPEN or PENDING claim of theirs dated within a hold counts in no live total, unless a statement
-- binds it. A person held before holds had dates keeps a hold from the beginning of time, with no end.
CREATE TABLE person_hold (
    person_id BIGINT NOT NULL REFERENCES person (id),
    hold_from DATE   NOT NULL,
    hold_to   DATE
);
CREATE INDEX person_hold_person ON person_hold (person_id);
INSERT INTO person_hold (person_id, hold_from, hold_to) SELECT id, DATE '0001-01-01', NULL FROM person WHERE held;
ALTER TABLE person DROP COLUMN held;
-- Whether a person is on hold. While held, their OPEN claims count in no live total (their own,
-- the sheet's or a period's); their SETTLED claims still count.
ALTER TABLE person ADD COLUMN held BOOLEAN DEFAULT FALSE NOT NULL;

